-- Revert 073: these registry and WinGet version shapes are not semantically
-- equivalent. Keep them intelligence-only/lagging rather than over-normalize.
UPDATE rmm_software_vendor_bindings SET metadata=(metadata-'versionNormalization') || jsonb_build_object('wingetFallbackReady',false,'hasWingetFallback',false,'deploymentMode','intelligence_only','trustState','version_only') WHERE source_key IN ('registry_chocolatey_ccleaner','registry_chocolatey_everything');
UPDATE rmm_software_catalogue SET source_metadata=(source_metadata-'versionNormalization') || jsonb_build_object('wingetFallbackReady',false,'hasWingetFallback',false,'deploymentMode','intelligence_only','trustState','version_only'), qualification_state='intelligence_only', updated_at=now() WHERE external_key IN ('vendor:registry_chocolatey_ccleaner','vendor:registry_chocolatey_everything') AND tenant_id IS NULL;
UPDATE rmm_software_vendor_releases SET trust_state='version_only',trust_evidence=trust_evidence || jsonb_build_object('wingetFallbackReady',false),source_payload=source_payload || jsonb_build_object('trustState','version_only','deploymentMode','intelligence_only','wingetFallbackReady',false) WHERE source_key IN ('registry_chocolatey_ccleaner','registry_chocolatey_everything');
